+// Sales variance: what the sold dishes should have used against what the
+// ledger says was consumed.
+import { getItem } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** Per item, theoretical use (sales) vs actual use (consume movements) between two days, inclusive. */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = instant.slice(0, 10);
+    return day >= from && day <= to;
+  };
+  const theo = new Map();
+  const actual = new Map();
+  for (const sale of store.data.sales ?? []) {
+    for (const line of sale.lines) {
+      if (!inRange(line.soldAt)) continue;
+      const recipe = getRecipe(store, getDish(store, line.dishId).recipeId);
+      for (const n of scaled(recipe, line.qty)) theo.set(n.itemId, (theo.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  return [...new Set([...theo.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = round3(theo.get(itemId) ?? 0);
+      const a = round3(actual.get(itemId) ?? 0);
+      return { itemId, name: getItem(store, itemId).name, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
